CREATE VIEW "Z_TEST_PRODUCTION_20250925"."B1_SnBTransRptFirstBinView" ( "ITLEntry", "SnBMDAbs", "BinCode", "SnBTransRptFirstBinViewBinCount" ) AS SELECT T0."ITLEntry", T0."SnBMDAbs", MIN(T1."BinCode") AS "BinCode", COUNT(DISTINCT T1."AbsEntry") AS "SnBTransRptFirstBinViewBinCount" FROM  "Z_TEST_PRODUCTION_20250925"."OBTL" T0  INNER  JOIN "Z_TEST_PRODUCTION_20250925"."OBIN" T1  ON  T0."BinAbs" = T1."AbsEntry"   WHERE T0."ITLEntry" <> (-1 )   GROUP BY T0."ITLEntry", T0."SnBMDAbs" WITH READ ONLY